import re
import math
from decimal import Decimal, InvalidOperation, Overflow

class ExpressionParser:
    """
    A high-precision Recursive Descent Parser for evaluating chained standard and
    scientific arithmetic expressions following PE(Unary)MDAS guidelines.
    """
    def __init__(self, expression: str, angle_unit: str = "radians"):
        self.expression = expression
        self.angle_unit = angle_unit.lower()
        self.tokens = self._tokenize(expression)
        self.pos = 0

    def _tokenize(self, expr: str) -> list[str]:
        if not expr.strip():
            raise ValueError("Expression is empty")

        # Match numbers (including decimals), words (functions/constants), operators (including ^), or whitespace
        pattern = re.compile(r'(\d*\.?\d+)|([a-zA-Z_][a-zA-Z0-9_]*)|([+\-*/()^])|(\s+)')
        tokens = []
        last_end = 0

        for match in pattern.finditer(expr):
            if match.start() != last_end:
                raise ValueError("Expression contains invalid characters")
            last_end = match.end()

            num, word, op, ws = match.groups()
            if num:
                tokens.append(num)
            elif word:
                tokens.append(word.lower())
            elif op:
                tokens.append(op)
            # Whitespace is ignored

        if last_end != len(expr):
            raise ValueError("Expression contains invalid characters")

        if not tokens:
            raise ValueError("Expression is empty")

        return tokens

    def _peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self, expected: str | None = None) -> str:
        token = self._peek()
        if token is None:
            if expected:
                raise ValueError(f"Expected '{expected}' but reached end of expression")
            raise ValueError("Unexpected end of expression")
        if expected and token != expected:
            raise ValueError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    def parse(self) -> Decimal:
        result = self._expr()
        if self.pos < len(self.tokens):
            raise ValueError(f"Unexpected token '{self.tokens[self.pos]}' at position {self.pos}")
        return result

    def _expr(self) -> Decimal:
        # expr -> term { ('+' | '-') term }
        val = self._term()
        while True:
            op = self._peek()
            if op in ('+', '-'):
                self._consume()
                right = self._term()
                if op == '+':
                    val = val + right
                else:
                    val = val - right
            else:
                break
        return val

    def _term(self) -> Decimal:
        # term -> unary { ('*' | '/') unary }
        val = self._unary()
        while True:
            op = self._peek()
            if op in ('*', '/'):
                self._consume()
                right = self._unary()
                if op == '*':
                    val = val * right
                else:
                    if right == Decimal('0'):
                        raise ZeroDivisionError("Division by zero")
                    val = val / right
            else:
                break
        return val

    def _unary(self) -> Decimal:
        # unary -> [ '+' | '-' ] power
        token = self._peek()
        is_negative = False

        if token == '-':
            is_negative = True
            self._consume()
        elif token == '+':
            self._consume()

