            elif op:
                tokens.append(op)
            # Whitespace is ignored

        if last_end != len(expr):
            raise ValueError("Expression contains invalid characters")

        if not tokens:
            raise ValueError("Expression is empty")

        return tokens

    def _peek(self) -> str | None:
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def _consume(self, expected: str | None = None) -> str:
        token = self._peek()
        if token is None:
            if expected:
                raise ValueError(f"Expected '{expected}' but reached end of expression")
            raise ValueError("Unexpected end of expression")
        if expected and token != expected:
            raise ValueError(f"Expected '{expected}' but found '{token}'")
        self.pos += 1
        return token

    def parse(self) -> Decimal:
        result = self._expr()
        if self.pos < len(self.tokens):
            raise ValueError(f"Unexpected token '{self.tokens[self.pos]}' at position {self.pos}")
        return result

    def _expr(self) -> Decimal:
        # expr -> term { ('+' | '-') term }
        val = self._term()
        while True:
            op = self._peek()
            if op in ('+', '-'):
                self._consume()
                right = self._term()
                if op == '+':
                    val = val + right
                else:
                    val = val - right
            else:
                break
        return val

    def _term(self) -> Decimal:
        # term -> unary { ('*' | '/') unary }
        val = self._unary()
        while True:
            op = self._peek()
            if op in ('*', '/'):
                self._consume()
                right = self._unary()
                if op == '*':
                    val = val * right
                else:
                    if right == Decimal('0'):
                        raise ZeroDivisionError("Division by zero")
                    val = val / right
            else:
                break
        return val

    def _unary(self) -> Decimal:
        # unary -> [ '+' | '-' ] power
        token = self._peek()
        is_negative = False

        if token == '-':
            is_negative = True
            self._consume()
        elif token == '+':
            self._consume()

        val = self._power()
        return -val if is_negative else val

    def _power(self) -> Decimal:
        # power -> primary [ '^' unary ]
        val = self._primary()
        if self._peek() == '^':
            self._consume('^')
            # Binary power operator is right-associative (or we can parse unary as exponent)
            exponent = self._unary()
            try:
                if exponent % 1 != 0:
                    if val < 0:
                        raise ValueError("Negative number raised to a fractional power is not allowed")
