          const evalResult = String(data.result);
          setResult(evalResult);
          valueToUse = Number(evalResult);
          setHistory((prev) => [{ expression, result: evalResult }, ...prev]);
        } else {
          throw new Error('Failed to evaluate for memory subtract');
        }
