  }, []);

  // History reload actions
  const handleReloadExpression = useCallback((histExpr: string) => {
    setError(null);
    setExpression(histExpr);
    setResult('');
  }, []);

  const handleAppendResult = useCallback((histRes: string) => {
    setError(null);
    setExpression((prev) => prev + histRes);
  }, []);

