  const handleMemoryAdd = useCallback(async () => {
    let valueToUse = 0;

    if (result && !isNaN(Number(result))) {
      valueToUse = Number(result);
    } else if (expression.trim() && !isNaN(Number(expression))) {
      valueToUse = Number(expression);
