    render(<App />);

    // Add complex expression and click M+
    fireEvent.click(screen.getByRole('button', { name: '5' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add' }));
    fireEvent.click(screen.getByRole('button', { name: '2' }));
    fireEvent.click(screen.getByRole('button', { name: 'Add display to memory' }));

    await waitFor(() => {
      expect(screen.getByText('Error evaluating for memory add')).toBeInTheDocument();
    });

    // Same for M-
    vi.spyOn(window, 'fetch').mockResolvedValue({
      ok: false,
      json: async () => ({
        detail: {
          type: 'error',
          message: 'Error evaluating for memory subtract',
        }
      }),
    } as Response);

    fireEvent.click(screen.getByRole('button', { name: 'Subtract display from memory' }));

    await waitFor(() => {
      expect(screen.getByText('Error evaluating for memory subtract')).toBeInTheDocument();
